import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.DrWxItG4.js";const g=JSON.parse('{"title":"Relay (watching the official client)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/relay.md","filePath":"guide/relay.md"}'),i={name:"guide/relay.md"};function s(o,e,c,p,d,l){return a(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="relay-watching-the-official-client" tabindex="-1">Relay (watching the official client) <a class="header-anchor" href="#relay-watching-the-official-client" aria-label="Permalink to &quot;Relay (watching the official client)&quot;">​</a></h1><p>On your own server you don&#39;t need to intercept anything to see packets:</p><ul><li><strong>Server side:</strong> <code>receive()</code> in <code>include/eventType/receive.cpp</code> sees every packet a client sends (it already prints text packets), and <code>send_data()</code> / <code>send_varlist()</code> see everything the server sends.</li><li><strong>Client side:</strong> <a href="/gtps-guide/guide/talk-to-server">hello.cpp</a> prints every packet it receives.</li></ul><p>To see what the <strong>official app</strong> sends, put a relay between it and your server:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Growtopia app ──▶ relay :17092 ──▶ gurotopia :17091</span></span>
<span class="line"><span>              ◀──              ◀──</span></span></code></pre></div><ol><li>Run an ENet <strong>server</strong> on 17092 with <code>usingNewPacketForServer</code>, CRC32 and the range coder, and an ENet <strong>client</strong> that connects to 17091 with <code>usingNewPacket</code>, CRC32 and the range coder (<a href="/gtps-guide/guide/transport">Transport</a>).</li><li>Point the app at the relay: <code>port|17092</code> in <code>server_data.php</code>.</li><li>When the app connects, open a connection to the real server for it. Forward every packet in both directions unchanged, and log or edit what you want. Read the first 4 bytes for the <a href="/gtps-guide/guide/message-types">message type</a>, and for type 4 the <a href="/gtps-guide/guide/game-packet">header</a>.</li><li>Rewrite <a href="/gtps-guide/functions/OnSendToServer">OnSendToServer</a> on its way to the app so its ip and port point at the relay again. Otherwise the app reconnects straight to the real server and leaves the relay.</li></ol><p>A relay only sees traffic after the HTTPS <code>server_data.php</code> step, so it doesn&#39;t help an app that rejects your certificate (<a href="/gtps-guide/guide/login">Login</a>). Use it with clients that reach your server, such as the Windows app with your certificate installed.</p><p>Only run a relay against servers you operate.</p>`,8)])])}const u=t(i,[["render",s]]);export{g as __pageData,u as default};
